bad = []
for f, (h, text) in FILES.items():
    ast.parse(text)
    p = pathlib.Path(f)
    if p.exists() and p.read_text() == text:      # もう版98 の形（先に置いた道具）なら、そのままで良い
        continue
    if h is None:
        if p.exists():
            bad.append(f + "（もうある）")
    elif not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest() != h:
        bad.append(f)
if bad:
    sys.exit(f"⚠️ {bad} が版97 を当てたままの形ではない（手で直した所があるか、版が違う）。何も書き換えていない")
for f, (_, text) in FILES.items():
    pathlib.Path(f).write_text(text)
print("✅ 版98 を当てた（小脳の切片）。⚠️ 網の形が変わるので state.pt は 0 から")
